arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.ML.Transforms;
using Microsoft.Extensions.ML;
using ChurnPredictor;

var builder = WebApplication.CreateBuilder(args);

var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" string to bool Label using a factory class (serializable)
var labelLookup = mlContext.Data.LoadFromEnumerable(new[]
{
    new LabelLookup { Churned = "Yes", Label = true },
    new LabelLookup { Churned = "No", Label = false },
});

var pipeline = mlContext.Transforms.Conversion
        .MapValue("Label", labelLookup, labelLookup.Schema["Churned"], labelLookup.Schema["Label"],
            inputColumnName: nameof(CustomerData.Churned))
    .Append(mlContext.Transforms.Categorical
        .OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        nameof(CustomerData.PurchaseHistory),
        "RegionEncoded"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

// Evaluate via cross-validation (dataset is small)
var cvResults = mlContext.BinaryClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3);
foreach (var (fold, result) in cvResults.Select((r, i) => (i + 1, r)))
{
    Console.WriteLine($"Fold {fold} — Accuracy: {result.Metrics.Accuracy:F4}, AUC: {result.Metrics.AreaUnderRocCurve:F4}, F1: {result.Metrics.F1Score:F4}");
}

// Train final model on all data
var model = pipeline.Fit(dataView);

// Save model and register pooled prediction engine
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");
mlContext.Model.Save(model, dataView.Schema, modelPath);

builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel ? "Yes" : "No",
        prediction.Probability,
        prediction.Score,
    });
});

app.Run();

